-- Baseline schema, ported from the TypeScript repo's migrations.
--
-- Consolidates Node's 0000_initial_schema, 0001_rls_and_views, 0002 (Bank of
-- Baroda) and 0003 (1-month window) into one transaction. Two deltas are folded
-- into their CREATE TYPE rather than applied as ALTER TYPE, because
-- `ALTER TYPE ... ADD VALUE` cannot run inside a transaction block:
--
--   * institution  gains 'bob'
--   * parse_engine gains 'table_extract'  (§7.2 — the free geometry engine)
--
-- Do not edit this file to change the schema; add a new Alembic revision.

CREATE EXTENSION IF NOT EXISTS pgcrypto;   -- gen_random_uuid()
CREATE EXTENSION IF NOT EXISTS pg_trgm;    -- merchant matching (§9)

CREATE TYPE "public"."account_source" AS ENUM('detected', 'user_added');
CREATE TYPE "public"."account_type" AS ENUM('savings', 'credit_card', 'loan');
CREATE TYPE "public"."category_kind" AS ENUM('spend', 'income', 'transfer');
CREATE TYPE "public"."consent_purpose" AS ENUM('statement_analysis', 'password_guessing', 'push_notifications');
CREATE TYPE "public"."coverage_status" AS ENUM('received', 'locked', 'missing', 'needs_review');
CREATE TYPE "public"."direction" AS ENUM('debit', 'credit');
CREATE TYPE "public"."document_kind" AS ENUM('statement_pdf');
CREATE TYPE "public"."document_status" AS ENUM('queued', 'locked', 'parsing', 'needs_review', 'done', 'failed');
CREATE TYPE "public"."email_connection_status" AS ENUM('active', 'revoked', 'error');
CREATE TYPE "public"."email_provider" AS ENUM('gmail');
CREATE TYPE "public"."insight_status" AS ENUM('new', 'seen', 'dismissed');
CREATE TYPE "public"."insight_type" AS ENUM('category_trend', 'duplicate_subscription', 'fees', 'upi_to_people', 'upcoming_renewal', 'biggest_month', 'coverage_gap');
CREATE TYPE "public"."institution" AS ENUM('hdfc', 'icici', 'sbi', 'axis', 'kotak', 'bob', 'unknown');
CREATE TYPE "public"."job_status" AS ENUM('queued', 'running', 'succeeded', 'failed');
CREATE TYPE "public"."parse_engine" AS ENUM('bank_parser', 'ocr', 'llm', 'table_extract');
CREATE TYPE "public"."plan" AS ENUM('free', 'pro');
CREATE TYPE "public"."raw_message_kind" AS ENUM('statement', 'txn_alert', 'ignore');
CREATE TYPE "public"."rule_match_kind" AS ENUM('merchant', 'vpa', 'text');
CREATE TYPE "public"."secret_kind" AS ENUM('pdf_password');
CREATE TYPE "public"."transaction_source" AS ENUM('statement', 'alert', 'manual');
CREATE TABLE "accounts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"institution" "institution" NOT NULL,
	"type" "account_type" NOT NULL,
	"masked_number" varchar(4),
	"nickname" varchar(60),
	"source" "account_source" DEFAULT 'detected' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "accounts_masked_number" CHECK ("accounts"."masked_number" is null or "accounts"."masked_number" ~ '^[0-9]{4}$')
);

CREATE TABLE "backfill_runs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"connection_id" uuid NOT NULL,
	"window_months" integer NOT NULL,
	"state" varchar(16) DEFAULT 'pending' NOT NULL,
	"messages_found" integer DEFAULT 0 NOT NULL,
	"messages_processed" integer DEFAULT 0 NOT NULL,
	"statements_found" integer DEFAULT 0 NOT NULL,
	"alerts_found" integer DEFAULT 0 NOT NULL,
	"next_page_token" text,
	"started_at" timestamp with time zone,
	"finished_at" timestamp with time zone,
	"error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "categories" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"slug" varchar(64) NOT NULL,
	"name" varchar(64) NOT NULL,
	"parent_id" uuid,
	"kind" "category_kind" NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "categories_slug_unique" UNIQUE("slug")
);

CREATE TABLE "data_exports" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"status" "job_status" DEFAULT 'queued' NOT NULL,
	"include_pdfs" boolean DEFAULT true NOT NULL,
	"storage_key" text,
	"expires_at" timestamp with time zone,
	"error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"finished_at" timestamp with time zone
);

CREATE TABLE "documents" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"raw_message_id" uuid,
	"account_id" uuid,
	"kind" "document_kind" DEFAULT 'statement_pdf' NOT NULL,
	"filename" varchar(255) NOT NULL,
	"storage_key" text NOT NULL,
	"sha256" varchar(64) NOT NULL,
	"size_bytes" integer,
	"encrypted" boolean DEFAULT false NOT NULL,
	"institution" "institution",
	"status" "document_status" DEFAULT 'queued' NOT NULL,
	"parse_engine" "parse_engine",
	"error" text,
	"unlock_attempts" integer DEFAULT 0 NOT NULL,
	"processed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "email_connections" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"provider" "email_provider" DEFAULT 'gmail' NOT NULL,
	"google_email" varchar(320) NOT NULL,
	"refresh_token_ciphertext" text NOT NULL,
	"refresh_token_nonce" text NOT NULL,
	"refresh_token_key_id" varchar(64) NOT NULL,
	"scopes" text[] NOT NULL,
	"history_id" varchar(32),
	"watch_expires_at" timestamp with time zone,
	"status" "email_connection_status" DEFAULT 'active' NOT NULL,
	"last_synced_at" timestamp with time zone,
	"last_error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "insights" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"type" "insight_type" NOT NULL,
	"title" varchar(120) NOT NULL,
	"body" text NOT NULL,
	"payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"period" varchar(7),
	"status" "insight_status" DEFAULT 'new' NOT NULL,
	"dedupe_key" varchar(128) NOT NULL,
	"notified_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "jobs_log" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid,
	"run_id" uuid,
	"queue" varchar(32) NOT NULL,
	"job" varchar(64) NOT NULL,
	"bull_job_id" varchar(128),
	"status" "job_status" DEFAULT 'queued' NOT NULL,
	"attempt" integer DEFAULT 1 NOT NULL,
	"started_at" timestamp with time zone,
	"finished_at" timestamp with time zone,
	"duration_ms" integer,
	"error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "llm_usage" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"day" date NOT NULL,
	"model" varchar(64) NOT NULL,
	"prompt_id" varchar(64) NOT NULL,
	"input_tokens" integer DEFAULT 0 NOT NULL,
	"output_tokens" integer DEFAULT 0 NOT NULL,
	"cost_micros" bigint DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "merchants" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"normalized_name" varchar(120) NOT NULL,
	"aliases" text[] DEFAULT '{}'::text[] NOT NULL,
	"default_category_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "merchants_normalized_name_unique" UNIQUE("normalized_name")
);

CREATE TABLE "oauth_states" (
	"state" varchar(128) PRIMARY KEY NOT NULL,
	"user_id" uuid NOT NULL,
	"return_path" varchar(256) NOT NULL,
	"code_verifier" text,
	"consumed_at" timestamp with time zone,
	"expires_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "push_subscriptions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"endpoint" text NOT NULL,
	"p256dh" text NOT NULL,
	"auth" text NOT NULL,
	"user_agent" varchar(200),
	"last_success_at" timestamp with time zone,
	"failure_count" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "raw_messages" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"connection_id" uuid,
	"provider_msg_id" varchar(128) NOT NULL,
	"from_addr" varchar(320) NOT NULL,
	"subject" text,
	"received_at" timestamp with time zone NOT NULL,
	"kind" "raw_message_kind" NOT NULL,
	"institution" "institution",
	"storage_key" text,
	"sha256" varchar(64) NOT NULL,
	"processed_at" timestamp with time zone,
	"body_deleted_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "report_cache" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"window_months" integer NOT NULL,
	"payload" jsonb NOT NULL,
	"schema_version" integer DEFAULT 1 NOT NULL,
	"generated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "secrets" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"account_id" uuid,
	"kind" "secret_kind" NOT NULL,
	"ciphertext" text NOT NULL,
	"nonce" text NOT NULL,
	"key_id" varchar(64) NOT NULL,
	"consented_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "statements" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"account_id" uuid NOT NULL,
	"document_id" uuid,
	"period_start" date NOT NULL,
	"period_end" date NOT NULL,
	"opening_balance" bigint,
	"closing_balance" bigint,
	"reconciled" boolean DEFAULT false NOT NULL,
	"reconcile_difference" bigint,
	"parse_engine" "parse_engine",
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "transactions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"account_id" uuid NOT NULL,
	"statement_id" uuid,
	"source" "transaction_source" NOT NULL,
	"txn_date" date NOT NULL,
	"amount_paise" bigint NOT NULL,
	"direction" "direction" NOT NULL,
	"raw_description" text NOT NULL,
	"merchant_id" uuid,
	"counterparty_vpa" varchar(120),
	"counterparty_name" varchar(80),
	"ref_no" varchar(64),
	"category_id" uuid,
	"category_confidence" real,
	"category_source" varchar(24),
	"is_transfer" boolean DEFAULT false NOT NULL,
	"is_recurring" boolean DEFAULT false NOT NULL,
	"superseded_by" uuid,
	"fingerprint" varchar(64) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "transactions_amount_positive" CHECK ("transactions"."amount_paise" >= 0)
);

CREATE TABLE "user_consents" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"purpose" "consent_purpose" NOT NULL,
	"granted_at" timestamp with time zone DEFAULT now() NOT NULL,
	"revoked_at" timestamp with time zone,
	"notice_version" varchar(32) NOT NULL
