CREATE TABLE "user_rules" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"match_kind" "rule_match_kind" NOT NULL,
	"match_value" varchar(160) NOT NULL,
	"category_id" uuid NOT NULL,
	"created_from_txn_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "users" (
	"id" uuid PRIMARY KEY NOT NULL,
	"email" varchar(320) NOT NULL,
	"display_name" varchar(80),
	"plan" "plan" DEFAULT 'free' NOT NULL,
	"pro_waitlist_at" timestamp with time zone,
	"analysis_window_months" integer DEFAULT 6 NOT NULL,
	"date_of_birth" date,
	"deletion_requested_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "users_window_months" CHECK ("users"."analysis_window_months" in (1, 3, 6, 12))
);

