-- Row-level security and the report aggregates.
--
-- Every user-owned table carries `user_id` and is protected by a policy keyed on
-- `app.user_id`, the setting `withUser()` sets for the life of a transaction.
-- On Supabase, `auth.uid()` is the same value when the request arrives through
-- PostgREST, so the policy accepts either source.

-- The role every user-scoped query runs as. No BYPASSRLS, no LOGIN: it is only
-- ever reached through `SET LOCAL ROLE` from a connection the API owns.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_user') THEN
    CREATE ROLE app_user NOLOGIN NOBYPASSRLS;
  END IF;
END
$$;

GRANT USAGE ON SCHEMA public TO app_user;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_user;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app_user;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_user;

-- Resolves the current user from the transaction setting, or from Supabase's
-- `auth.uid()` when the request came through PostgREST. Returns NULL when
-- neither is set, and a NULL never matches a policy, so the default is deny.
CREATE OR REPLACE FUNCTION public.current_app_user_id()
RETURNS uuid
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  raw text;
BEGIN
  raw := current_setting('app.user_id', true);
  IF raw IS NOT NULL AND raw <> '' THEN
    RETURN raw::uuid;
  END IF;
  BEGIN
    RETURN auth.uid();
  EXCEPTION WHEN undefined_function OR invalid_schema_name THEN
    RETURN NULL;
  END;
END;
$$;

-- Owned tables: a row is visible only to the user whose id it carries, and a
-- write may not hand a row to somebody else (the WITH CHECK clause).
DO $$
DECLARE
  t text;
  owned text[] := ARRAY[
    'users', 'user_consents', 'email_connections', 'oauth_states', 'raw_messages',
    'documents', 'accounts', 'statements', 'transactions', 'user_rules', 'insights',
    'secrets', 'push_subscriptions', 'jobs_log', 'backfill_runs', 'data_exports',
    'llm_usage', 'report_cache'
  ];
  id_column text;
BEGIN
  FOREACH t IN ARRAY owned LOOP
    -- `users` is keyed on `id`; every other owned table on `user_id`.
    id_column := CASE WHEN t = 'users' THEN 'id' ELSE 'user_id' END;

    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_owner', t);
    EXECUTE format(
      'CREATE POLICY %I ON public.%I
         FOR ALL
         TO app_user
         USING (%I = public.current_app_user_id())
         WITH CHECK (%I = public.current_app_user_id())',
      t || '_owner', t, id_column, id_column
    );
  END LOOP;
END
$$;

-- Reference data is shared and read-only for app_user: a merchant dictionary and
-- a category list are not personal data, and only the worker writes to them.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['categories', 'merchants'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_read', t);
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR SELECT TO app_user USING (true)',
      t || '_read', t
    );
    EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON public.%I FROM app_user', t);
  END LOOP;
END
$$;

-- ── Report aggregates ──────────────────────────────────────────────────────
--
-- Views, not materialised views: `REFRESH MATERIALIZED VIEW` cannot refresh one
-- tenant's slice, and refreshing every tenant because one statement arrived
-- does not scale. The insights agent reads these and writes the finished
-- payload to `report_cache` for the user that changed.
--
-- Every view is `security_invoker`. Without it a view runs as its owner, the
-- underlying table's RLS is checked against that owner, and the view hands back
-- every tenant's rows. There is a test for this in `test/rls.test.ts`.

-- Rows the report is allowed to count: never a superseded alert row, never a
-- row from a statement that failed the reconciliation gate.
CREATE OR REPLACE VIEW public.v_publishable_transactions
  WITH (security_invoker = true) AS
SELECT t.*
FROM public.transactions t
LEFT JOIN public.statements s ON s.id = t.statement_id
WHERE t.superseded_by IS NULL
  AND (t.statement_id IS NULL OR s.reconciled);

-- Spend excludes transfers between the user's own accounts (paying the card
-- from savings is not spending) and counts by transaction date, never by
-- statement month.
CREATE OR REPLACE VIEW public.v_monthly_spend
  WITH (security_invoker = true) AS
SELECT
  t.user_id,
  to_char(t.txn_date, 'YYYY-MM')                                      AS month,
  SUM(t.amount_paise) FILTER (WHERE t.direction = 'debit')            AS spent_paise,
  SUM(t.amount_paise) FILTER (WHERE t.direction = 'credit')           AS received_paise,
  COUNT(*)                                                            AS txn_count
FROM public.v_publishable_transactions t
WHERE NOT t.is_transfer
GROUP BY t.user_id, to_char(t.txn_date, 'YYYY-MM');

CREATE OR REPLACE VIEW public.v_category_spend
  WITH (security_invoker = true) AS
SELECT
  t.user_id,
  to_char(t.txn_date, 'YYYY-MM')  AS month,
  t.category_id,
  c.slug                          AS category_slug,
  c.name                          AS category_name,
  c.kind                          AS category_kind,
  SUM(t.amount_paise)             AS amount_paise,
  COUNT(*)                        AS txn_count
FROM public.v_publishable_transactions t
LEFT JOIN public.categories c ON c.id = t.category_id
WHERE NOT t.is_transfer
  AND t.direction = 'debit'
GROUP BY t.user_id, to_char(t.txn_date, 'YYYY-MM'), t.category_id, c.slug, c.name, c.kind;

-- One row per account and month that a statement actually covers. The coverage
-- grid diffs this against the months in the analysis window to find the gaps.
CREATE OR REPLACE VIEW public.v_statement_coverage
  WITH (security_invoker = true) AS
SELECT
  s.user_id,
  s.account_id,
  to_char(gs.month, 'YYYY-MM') AS month,
  s.id                         AS statement_id,
  s.document_id,
  s.reconciled
FROM public.statements s
CROSS JOIN LATERAL generate_series(
  date_trunc('month', s.period_start),
  date_trunc('month', s.period_end),
  interval '1 month'
) AS gs(month);

-- Money sent to people by UPI: a VPA with no merchant attached to it.
CREATE OR REPLACE VIEW public.v_upi_counterparties
  WITH (security_invoker = true) AS
SELECT
  t.user_id,
  t.counterparty_vpa                                            AS vpa,
  MAX(t.counterparty_name)                                      AS display_name,
  SUM(t.amount_paise) FILTER (WHERE t.direction = 'debit')      AS sent_paise,
  SUM(t.amount_paise) FILTER (WHERE t.direction = 'credit')     AS received_paise,
  COUNT(*)                                                      AS txn_count,
  MAX(t.txn_date)                                               AS last_seen
FROM public.v_publishable_transactions t
WHERE t.counterparty_vpa IS NOT NULL
  AND t.merchant_id IS NULL
  AND NOT t.is_transfer
GROUP BY t.user_id, t.counterparty_vpa;

GRANT SELECT ON public.v_publishable_transactions, public.v_monthly_spend,
  public.v_category_spend, public.v_statement_coverage, public.v_upi_counterparties
  TO app_user;
